package main

import (
	_ "embed"
	"encoding/binary"
	"time"
	"unsafe"
)

func sleepMs(ms int) { time.Sleep(time.Duration(ms) * time.Millisecond) }

// The Velo icon, generated by tools/mkicon (go run ./tools/mkicon).
//
//go:embed assets/velo.ico
var veloICO []byte

// appIcon is the multi-size .ico used for the tray icon.
func appIcon() []byte { return veloICO }

// iconPNG returns the PNG image of the given size from velo.ico (the
// closest larger one if that size isn't present).
func iconPNG(size int) []byte {
	n := int(binary.LittleEndian.Uint16(veloICO[4:]))
	var best []byte
	bestDim := 1 << 30
	for i := 0; i < n; i++ {
		e := veloICO[6+16*i:]
		dim := int(e[0])
		if dim == 0 {
			dim = 256
		}
		ln := binary.LittleEndian.Uint32(e[8:])
		off := binary.LittleEndian.Uint32(e[12:])
		if dim >= size && dim < bestDim {
			best, bestDim = veloICO[off:off+ln], dim
		}
	}
	return best
}

// hIcon creates a Windows icon handle of the given size.
func hIcon(size int) uintptr {
	png := iconPNG(size)
	if png == nil {
		return 0
	}
	h, _, _ := pCreateIconFromResEx.Call(uintptr(unsafe.Pointer(&png[0])), uintptr(len(png)), 1, 0x00030000,
		uintptr(size), uintptr(size), 0)
	return h
}

var pSendMessageW = user32n.NewProc("SendMessageW")

// setWindowIcon gives a window the Velo icon in its title bar, taskbar and
// Alt+Tab (WM_SETICON small and big).
func setWindowIcon(hwnd uintptr) {
	const wmSetIcon, iconSmall, iconBig = 0x80, 0, 1
	if h := hIcon(16); h != 0 {
		pSendMessageW.Call(hwnd, wmSetIcon, iconSmall, h)
	}
	if h := hIcon(48); h != 0 {
		pSendMessageW.Call(hwnd, wmSetIcon, iconBig, h)
	}
}
